html:
{%- set holder = doc.user_full_name or doc.user -%}
<div class="qr-card">
	<style>
		.qr-card { font-family: "Inter", sans-serif; color: #171717; max-width: 420px; margin: 0 auto; }
		.qr-card .heading { font-size: 20px; font-weight: 600; margin-bottom: 2px; }
		.qr-card .muted { color: #7c7c7c; font-size: 12px; }
		.qr-card .frame { border: 1px solid #ededed; border-radius: 10px; padding: 24px; text-align: center; }
		.qr-card img.qr { width: 240px; height: 240px; image-rendering: pixelated; }
		.qr-card table { width: 100%; border-collapse: collapse; margin-top: 16px; }
		.qr-card td { padding: 6px 0; font-size: 12px; border-top: 1px solid #f5f5f5; }
		.qr-card td.k { text-align: left; color: #7c7c7c; width: 45%; }
		.qr-card td.v { text-align: right; font-weight: 500; }
		.qr-card .footer { margin-top: 18px; font-size: 11px; color: #8a8a8a; line-height: 1.5; }
		.qr-card .warn { color: #b42318; }
	</style>

	<div class="heading">{{ _("Login QR Credential") }}</div>
	<div class="muted">{{ _("Present this code at a QR-enabled terminal to sign in.") }}</div>

	<div class="frame">
		{% if doc.status == "Active" and doc.qr_image_data %}
			<img class="qr" src="{{ doc.qr_image_data }}" alt="{{ _('Login QR code') }}">
		{% elif doc.status == "Revoked" %}
			<div class="warn" style="padding: 90px 0;">{{ _("This credential has been revoked.") }}</div>
		{% elif doc.status == "Superseded" %}
			<div class="warn" style="padding: 90px 0;">{{ _("This credential has been replaced.") }}</div>
		{% elif doc.status == "Expired" %}
			<div class="warn" style="padding: 90px 0;">{{ _("This credential has expired.") }}</div>
		{% else %}
			<div class="warn" style="padding: 90px 0;">{{ _("No QR image is available for this credential.") }}</div>
		{% endif %}
	</div>

	<table>
		<tr><td class="k">{{ _("Issued to") }}</td><td class="v">{{ holder }}</td></tr>
		<tr><td class="k">{{ _("Account") }}</td><td class="v">{{ doc.user }}</td></tr>
		<tr><td class="k">{{ _("Valid until") }}</td><td class="v">{{ frappe.utils.format_date(doc.expires_on) }}</td></tr>
		<tr><td class="k">{{ _("Status") }}</td><td class="v">{{ doc.status }}</td></tr>
		{% if doc.device_label %}
		<tr><td class="k">{{ _("Device") }}</td><td class="v">{{ doc.device_label }}</td></tr>
		{% endif %}
	</table>

	<div class="footer">
		{{ _("Keep this code private. Anyone who scans it can sign in as the named user until it expires or is revoked.") }}
		<br>
		{{ _("Reference") }}: {{ doc.token_prefix }}&hellip;
	</div>
</div>
